import {kindOf,isSaas,ongoing,annualMinor,daysTo,renewalDate,actionDate,money,summarize,portfolioCsv,csvCell,taxLabel} from './saas-metrics.js';
import {busyButton} from './analysis-progress.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const opt=a=>a?.[0];
const date=s=>s?new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(s+'T00:00:00Z')):'Not recorded';
const button=(text,id,primary=false)=>`<button type="button" class="pill ${primary?'primary':'outline'}" ${id?`id="${id}"`:''}>${text}</button>`;
const heading=(eyebrow,title,description,actions='')=>`<header class="saas-heading"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2><p>${description}</p></div><div class="btnrow">${actions}</div></header>`;
const empty=(title,detail,action='')=>`<div class="saas-empty"><span aria-hidden="true">◇</span><h3>${title}</h3><p>${detail}</p>${action}</div>`;
export async function renderSaas(root,ctx,page='overview',id=null){
 const {api,token,stale,space,download,toast}=ctx;
 root.innerHTML='<div class="saas-loading" role="status"><span class="reading-orbit">▤</span>Opening your SaaS workspace…</div>';
 let data;try{data=opt(await api.portfolio(token));}catch(_){if(!stale())root.innerHTML=empty('The workspace could not be loaded','Your records are safe. Reload to reconnect.',button('Try again','saasRetry'));root.querySelector('#saasRetry')?.addEventListener('click',()=>renderSaas(root,ctx,page,id));return;}
 if(stale())return;if(!data){root.innerHTML=empty('Session needs refreshing','Reopen Contracts from the Hub.');return;}
 const rows=data.rows;const stats=summarize(rows);let groups=[];
 const status=(el,text,bad=false)=>{el.textContent=text;el.className='saas-result'+(bad?' error':'');};
 const reload=()=>renderSaas(root,ctx,page,id);
 const saveAction=(form,fn)=>{let busy=false;form.onsubmit=async e=>{e.preventDefault();if(busy||stale())return;busy=true;const b=form.querySelector('[type=submit]'),reset=busyButton(b,'Saving…'),out=form.querySelector('[role=status]');try{const result=await fn(new FormData(form));if(stale())return;if(!result.ok)status(out,result.detail,true);else{toast(result.detail||'Saved');await reload();}}catch(_){if(!stale())status(out,'The save could not be confirmed. Reload before retrying.',true);}finally{busy=false;if(!stale())reset();}};};
 async function loadGroups(){if(!groups.length)groups=await api.directoryGroups(token);return groups;}
 function ownerPicker(input,hidden,initial){input.value=initial||'';let seq=0,timer;const list=document.createElement('div');list.className='saas-person-results';input.after(list);input.oninput=()=>{hidden.value='';const n=++seq;clearTimeout(timer);timer=setTimeout(async()=>{try{const people=await api.directory(token,input.value);if(stale()||n!==seq)return;list.innerHTML=people.map(p=>`<button type="button" data-pid="${esc(p.id)}"><strong>${esc(p.displayName)}</strong><small>${esc(p.email)}</small></button>`).join('');list.querySelectorAll('button').forEach(b=>b.onclick=()=>{const p=people.find(p=>p.id===b.dataset.pid);hidden.value=p.id;input.value=p.displayName;list.innerHTML='';});}catch(_){list.textContent='Directory temporarily unavailable';}},160);};}
 function rowsTable(list,keys=false){return `<div class="saas-table-scroll"><table class="saas-table ${keys?'saas-table-keys':''}"><thead><tr><th>Tool</th><th>Owner</th><th>Licenses</th>${keys?'<th>Expires</th><th>Key</th>':'<th>Annual cost</th><th>Contract period</th><th>Cancel by</th><th>Auto-renewal</th>'}<th>Status</th></tr></thead><tbody>${list.map(r=>{const c=r.contract,t=c.terms,d=daysTo(actionDate(c));return `<tr><td><a class="saas-tool" href="#/${keys?'keys':'c'}/${c.id}"><span class="tool-monogram">${esc((c.product||c.title).slice(0,1).toUpperCase())}</span><span><strong>${esc(c.product||c.title)}</strong><small>${esc(c.vendor)}</small></span></a></td><td>${esc(r.ownerName||'Assign an owner')}${r.groups.length?`<small>${r.groups.map(esc).join(', ')}</small>`:''}</td><td>${c.seats.length?`<strong>${Number(c.seats[0])}</strong><small>${Number(r.assigned)} assigned</small>`:'Not recorded'}</td>${keys?`<td>${t.end?date(t.end):'No expiry set'}</td><td><span class="key-mask">•••• •••• ••••</span></td>`:`<td class="cost">${money(annualMinor(t),t.currency)}<small>${t.taxBasis==='net'?'Excluding tax':t.taxBasis==='gross'?'Including tax':'Tax basis not stated'}</small></td><td>${date(t.start)}<small>to ${date(t.end||t.renewalDate)}</small></td><td><span class="${d!=null&&d<=30?'deadline-soon':''}">${date(t.noticeDate)}</span>${d!=null?`<small>${d<0?'Review overdue':d===0?'Decision today':d+' days to act'}</small>`:''}</td><td><span class="renewal-chip ${t.renewalRule==='auto'?'auto':''}">${esc({auto:'Yes',manual:'Manual renewal',none:'No',indefinite:'No fixed expiry'}[t.renewalRule]||'Needs review')}</span></td>`}<td><span class="saas-status ${esc(c.status)}">${esc({active:'Active',draft:'Offer / draft',cancelling:'Cancelling',ended:'Ended',endConfirmed:'End confirmed',archived:'Archived'}[c.status]||c.status)}</span></td></tr>`;}).join('')}</tbody></table></div>`;}
 if(page==='overview'){
  const upcoming=stats.renewals.slice(0,5),totals=stats.currencies.filter(b=>b.annual||b.missing);
  root.innerHTML=heading(esc(space.name)+' / SAAS MANAGEMENT','Know what renews. Stay ahead.','Your software, owners and renewal decisions in one place.',`<a class="pill outline" href="#/reports">Management report ↗</a><a class="pill primary" href="#/add">＋ Upload contract</a>`)+
   `<div class="saas-stats"><article class="saas-stat spending"><span>Annual SaaS run rate</span>${totals.length?totals.map(b=>`<strong>${money(b.annual,b.currency)}</strong><small>${taxLabel(b.taxBasis)}</small>`).join(''):'<strong>—</strong>'}<small>Recurring costs at current recorded rates</small></article><article class="saas-stat"><span>Active subscriptions</span><strong>${stats.active.length}</strong><small>${stats.subs.filter(r=>r.contract.status==='draft').length} offers awaiting a decision</small></article><article class="saas-stat"><span>Renewals to review</span><strong>${stats.renewals.length}</strong><small>Due within 90 days or overdue</small></article><article class="saas-stat"><span>Licenses unassigned</span><strong>${stats.active.reduce((n,r)=>n+(r.contract.seats.length?Math.max(0,Number(r.contract.seats[0])-Number(r.assigned)):0),0)}</strong><small>Purchased seats without recorded users</small></article></div>`+
   `<div class="saas-dashboard-grid"><section class="scard"><div class="section-title"><h3>Your next decisions</h3><a href="#/contracts">All subscriptions →</a></div>${upcoming.length?upcoming.map(r=>`<a class="renewal-row" href="#/c/${r.contract.id}"><span class="tool-monogram">${esc((r.contract.product||r.contract.title)[0])}</span><span><strong>${esc(r.contract.product||r.contract.title)}</strong><small>${esc(r.ownerName||'No owner assigned')} · ${money(annualMinor(r.contract.terms),r.contract.terms.currency)} / year</small></span><span class="renewal-due">${date(actionDate(r.contract))}<small>${r.contract.terms.noticeDate?'Cancellation deadline':'Renewal / expiry'}</small></span></a>`).join(''):empty('Nothing urgent on the horizon','Confirmed renewal and cancellation dates appear here automatically.')}<a class="saas-inline-link" href="#/settings">Reminders: ${data.policy.days.map(Number).join(', ')} days before renewal →</a></section><section class="scard saas-spend"><div class="section-title"><h3>Where your budget goes</h3></div>${totals.length?totals.map(b=>{const top=stats.active.filter(r=>r.contract.terms.currency===b.currency&&r.contract.terms.taxBasis===b.taxBasis&&annualMinor(r.contract.terms)!=null).sort((a,b)=>annualMinor(b.contract.terms)-annualMinor(a.contract.terms)).slice(0,4);return `<p class="eyebrow">${esc(b.currency)} · ${taxLabel(b.taxBasis)}</p>`+top.map(r=>`<a class="spend-row" href="#/c/${r.contract.id}"><span>${esc(r.contract.product||r.contract.title)}<b>${money(annualMinor(r.contract.terms),b.currency)}</b></span><i style="--bar:${Math.max(1,annualMinor(r.contract.terms)/Math.max(1,b.annual)*100)}%"></i></a>`).join('');}).join(''):empty('Start with one contract','AI reads the original and prepares the fields for you.','<a class="pill primary" href="#/add">Upload your first contract</a>')}</section></div>`+
   (stats.missing?`<p class="saas-footnote">${stats.missing} active subscription${stats.missing===1?' is':'s are'} missing a price, currency or billing frequency and ${stats.missing===1?'is':'are'} excluded from the run rate.</p>`:'')+`<p class="saas-footnote">Amounts stay separate by currency and tax basis. No exchange rate or payment status is assumed.</p>`;
 } else if(page==='subscriptions'||page==='keys'&&id==null){
  const keys=page==='keys';root.innerHTML=heading(keys?'LICENSE INVENTORY':'YOUR SOFTWARE',keys?'License keys':'SaaS subscriptions',keys?'Keep software keys, expiry dates and responsibility together. Keys stay hidden until you reveal them.':'The fields you need to make the next renewal decision.',keys?button('＋ Add license key','addKey',true):`<a class="pill outline" href="#/reports">Export report</a><a class="pill primary" href="#/add">＋ Upload contract</a>`)+`<div class="saas-toolbar"><input type="search" id="saasSearch" placeholder="Find a tool, vendor or owner…" aria-label="Search software"><select id="saasFilter" aria-label="Filter software"><option value="all">All ${keys?'keys':'subscriptions'}</option><option value="active">Active</option><option value="soon">Renewing or expiring soon</option><option value="incomplete">Missing details</option><option value="draft">Offers / drafts</option><option value="archived">Archived</option></select><span id="saasCount"></span></div><div id="saasRows"></div>`;
  const draw=()=>{const q=root.querySelector('#saasSearch').value.toLowerCase(),filter=root.querySelector('#saasFilter').value;const list=rows.filter(r=>{const c=r.contract;if(keys!== (kindOf(c)==='license-key')||!keys&&!isSaas(c))return false;if(filter!=='archived'&&c.status==='archived')return false;if(![c.title,c.product,c.vendor,r.ownerName,...r.groups].join(' ').toLowerCase().includes(q))return false;return filter==='all'||c.status===filter||filter==='soon'&&daysTo(actionDate(c))!=null&&daysTo(actionDate(c))<=90||filter==='incomplete'&&(!c.responsible||!c.terms.renewalRule||!renewalDate(c)||!keys&&annualMinor(c.terms)==null);});root.querySelector('#saasCount').textContent=list.length+' '+(keys?(list.length===1?'key':'keys'):(list.length===1?'subscription':'subscriptions'));root.querySelector('#saasRows').innerHTML=list.length?rowsTable(list,keys):empty(q?'No matches':'Everything starts with one tool',q?'Try another search.':keys?'Add your first software key.':'Upload a SaaS contract to get started.');};if(id==='soon')root.querySelector('#saasFilter').value='soon';draw();root.querySelector('#saasSearch').oninput=draw;root.querySelector('#saasFilter').onchange=draw;
  if(keys){root.querySelector('#addKey').hidden=!ctx.canWrite;root.querySelector('#addKey').onclick=()=>{location.hash='#/keys/new';};}
 } else if(page==='keys'){
  if(id==='new'&&!ctx.canWrite){root.innerHTML=empty('This workspace is read-only','A workspace editor or owner can add license keys.');return;}
  const r=rows.find(r=>String(r.contract.id)===String(id)),c=r?.contract;
  if(id!=='new'&&!c){root.innerHTML=empty('Key not available','It may have been removed or belong to another workspace.');return;}
  root.innerHTML=heading('LICENSE KEY',esc(c?.product||'Add a license key'),'Keys are restricted to their owner, named viewers and workspace owners.','<a class="pill outline" href="#/keys">Back to keys</a>')+`<form class="scard saas-key-form"><div class="review-fields"><label>Tool name<input name="tool" required maxlength="200" value="${esc(c?.title)}"></label><label>Vendor<input name="vendor" maxlength="200" value="${esc(c?.vendor)}"></label><label>Owner<input id="keyOwner" autocomplete="off" placeholder="Search Hub people…"><input name="ownerId" type="hidden" value="${esc(c?.responsible||ctx.me.id)}"></label><label>Licenses<input name="seats" type="number" min="0" step="1" value="${c?.seats?.[0]??''}"></label><label>Expiry date <small>Leave empty for a perpetual key</small><input name="expires" type="date" value="${esc(c?.terms.end)}"></label><label class="wide">${c?'Replace key (optional)':'License key'}<textarea name="key" rows="3" autocomplete="off" spellcheck="false" ${c?'':'required'} placeholder="${c?'Leave blank to keep the existing key':'Paste the license key'}"></textarea></label><label class="wide">Notes<textarea name="note" rows="2" maxlength="1200">${esc(c?.terms.note)}</textarea></label></div><div class="btnrow"><button class="pill primary" type="submit">Save license key</button>${c?button('Reveal saved key','revealKey')+'<a class="pill outline" href="#/c/'+c.id+'/seats">People &amp; licenses</a><a class="pill outline" href="#/c/'+c.id+'/history">Access history</a>':''}</div><div role="status"></div><div id="revealedKey" hidden></div></form>`;
  const form=root.querySelector('form');if(c&&!r.canEdit){form.querySelectorAll('input,textarea,[type=submit]').forEach(el=>el.disabled=true);form.querySelector('[type=submit]').hidden=true;}ownerPicker(root.querySelector('#keyOwner'),form.elements.ownerId,r?.ownerName||ctx.me.displayName);
  saveAction(form,async f=>{const res=await api.saveLicenseKey(token,c?[c.id]:[],c?.revision||0n,{tool:f.get('tool').trim(),vendor:f.get('vendor').trim(),ownerId:f.get('ownerId'),key:f.get('key').trim(),seats:f.get('seats')?[BigInt(f.get('seats'))]:[],expires:f.get('expires'),note:f.get('note')});if(res.ok){location.hash='#/keys';}return res;});
  const reveal=root.querySelector('#revealKey');if(reveal)reveal.onclick=async()=>{const reset=busyButton(reveal,'Opening…');try{const key=opt(await api.revealLicenseKey(token,c.id));if(stale())return;const el=root.querySelector('#revealedKey');el.hidden=false;el.textContent=key||'Key unavailable';el.className='revealed-key';setTimeout(()=>{el.textContent='';el.hidden=true;},20000);}catch(_){toast('Could not reveal the key');}finally{if(!stale())reset();}};
 } else if(page==='reports'){
  const thisYear=new Date().getUTCFullYear();root.innerHTML=heading('MANAGEMENT REPORT','Software spend, made clear.','Export a spreadsheet or print a management-ready report for this workspace.',button('Download CSV','reportCsv')+button('Print / save PDF','reportPrint',true))+`<div class="saas-toolbar no-print"><label>Reporting year <select id="reportYear">${Array.from({length:6},(_,i)=>thisYear-i).map(y=>`<option>${y}</option>`).join('')}</select></label></div><div id="reportBody"></div>`;
  const draw=()=>{const year=Number(root.querySelector('#reportYear').value),s=summarize(rows,year);root.querySelector('#reportBody').innerHTML=`<div class="report-intro"><strong>${esc(space.name)} · ${year}</strong><span>Prepared ${date(new Date().toISOString().slice(0,10))}</span></div><div class="saas-stats">${s.currencies.map(b=>`<article class="saas-stat"><span>${esc(b.currency)} · ${taxLabel(b.taxBasis)} · annual run rate now</span><strong>${money(b.annual,b.currency)}</strong><small>Estimated accrued cost in ${year}: ${money(b.accrued,b.currency)}<br>Recorded billing documents: ${money(b.documents,b.currency)}</small></article>`).join('')}</div><p class="saas-footnote">Run rate annualizes current recurring prices. Estimated accrued cost prorates recorded terms over their known dates, capped at today; saved price changes are respected. Earlier undocumented changes and undated costs are excluded. Billing documents use the document date recorded as start date and are not proof of payment; duplicates or separate invoice/receipt records may require reconciliation. Currencies and recorded tax bases are not converted.</p>${rowsTable(rows.filter(r=>isSaas(r.contract)))}`;};draw();root.querySelector('#reportYear').onchange=draw;
  root.querySelector('#reportCsv').onclick=()=>{const year=Number(root.querySelector('#reportYear').value),s=summarize(rows,year);const summary=[['Workspace',space.name],['Reporting year',year],['Currency','Tax basis','Current annual run rate','Estimated accrued cost','Recorded billing documents'],...s.currencies.map(b=>[b.currency,taxLabel(b.taxBasis),(b.annual/100).toFixed(2),(b.accrued/100).toFixed(2),(b.documents/100).toFixed(2)]),['Method','Accrual from recorded terms only; billing documents do not prove payment; currencies and tax bases not combined.']].map(row=>row.map(csvCell).join(',')).join('\r\n');download('saas-report-'+year+'.csv','\ufeff'+summary+'\r\n\r\n'+portfolioCsv(rows),'text/csv;charset=utf-8');};root.querySelector('#reportPrint').onclick=()=>window.print();
 } else if(page==='settings'){
  await loadGroups();if(stale())return;const p=data.policy;
  root.innerHTML=heading('WORKSPACE SETTINGS','Make renewals someone’s job.','Choose who hears about renewals. Delivery uses the existing Hub notification and Slack connection.')+`<div class="saas-settings-grid"><form class="scard"><h3>Renewal reminders</h3><p>The first reminder is 90 days before renewal or expiry. A cancellation deadline is also checked 90 days ahead so a long notice period cannot pass unnoticed.</p><label class="saas-check"><input type="checkbox" name="enabled" ${p.enabled?'checked':''}> Enable reminders for this workspace</label><div class="reminder-schedule">${p.days.map(Number).map(d=>`<span>${d}<small>days before</small></span>`).join('')}</div><label>Reminder days<input name="days" value="${p.days.map(Number).join(', ')}" required></label><h4>Recipients</h4>${[['owner','Contract owner'],['spaceOwners','Workspace owners'],['hubAdmins','Hub IT administrators and owners with access']].map(([k,l])=>`<label class="saas-check"><input name="${k}" type="checkbox" ${p[k]?'checked':''}> ${l}</label>`).join('')}<label>Additional Hub groups<select name="groups" multiple size="4">${groups.map(g=>`<option value="${esc(g.name)}" ${p.groups.includes(g.name)?'selected':''}>${esc(g.name)} (${Number(g.members)})</option>`).join('')}</select></label><p class="kv">Recipients must already have access to the contract. Selecting a group does not share contracts or license keys. Personal spaces remain private.</p><button type="submit" class="pill primary" ${data.canManage?'':'disabled'}>Save reminders</button><div role="status"></div>${data.canManage?'':'<p>Only workspace owners can change reminder settings.</p>'}</form><div><section class="scard"><span class="connection-dot"></span><h3>Connected to Hub</h3><div class="directory-numbers"><strong>${Number(data.people)}<small>active people</small></strong><strong>${groups.length}<small>groups received</small></strong></div><p>People and group membership refresh automatically with the Hub directory. Assign a group to a subscription to keep its license roster current.</p><p class="kv">Last directory update: ${data.directoryAt?new Date(Number(data.directoryAt)/1e6).toLocaleString():'Not received'}</p><a class="saas-inline-link" href="#/connection/status">Inspect connection →</a></section><section class="scard"><h3>Slack delivery</h3><p>Reminders enter the Hub notification outbox. Slack direct messages depend on the Hub bot connection and each recipient’s notification preferences.</p><a class="saas-inline-link" href="#/connection/status">Delivery status →</a></section><section class="scard"><h3>Setup &amp; data</h3><a class="settings-link" href="#/connection/ai">AI connection <span>→</span></a><a class="settings-link" href="#/mail-setup">Email intake setup <span>→</span></a><a class="settings-link" href="#/space">Members &amp; workspace <span>→</span></a><a class="settings-link" href="#/connection/export">Import &amp; export <span>→</span></a><a class="settings-link" href="#/trash">Trash <span>→</span></a><a class="settings-link" href="#/docs">How it works <span>→</span></a></section></div></div>`;
  const form=root.querySelector('form');saveAction(form,f=>{const days=String(f.get('days')).split(',').map(s=>s.trim());if(days.some(v=>!/^\d+$/.test(v)))return {ok:false,detail:'Enter whole numbers separated by commas, including 90.'};return api.setRenewalPolicy(token,{enabled:f.has('enabled'),owner:f.has('owner'),spaceOwners:f.has('spaceOwners'),hubAdmins:f.has('hubAdmins'),groups:f.getAll('groups'),days:days.map(BigInt)});});
 }
 if(!ctx.canWrite)root.querySelectorAll('a[href="#/add"]').forEach(a=>a.remove());
}
